create table t(a int, b text, c real);
insert into t values(1,'x',1.5),(2,'y',2.5),(3,'x',3.5),(4,'y',4.5),(5,'x',5.5),(6,'z',null),(7,'x',7),(8,'y',8),(9,'z',9),(10,'x',10);
explain select a, sum(a) over (order by a rows between 1 preceding and 1 following) from t;
explain select a, rank() over (partition by b order by a), lead(a) over (partition by b order by a) from t;
explain select a, min(c) over (order by a rows between 2 preceding and current row) from t;
explain select a, sum(a) over (order by b groups between 1 preceding and 1 following exclude ties) from t;
explain select a, count(*) over (order by c range between 1.0 preceding and 2.0 following) from t;
select a, sum(a) over (partition by b), avg(c) over (order by a), max(a) over (partition by b order by a desc) from t order by a;
select a, (select sum(x.a) over () from t x where x.a = t.a) from t;
select b, row_number() over (order by count(*) desc) from t group by b;
select a from t order by sum(a) over (order by a desc) limit 3;
create view v as select a, row_number() over (order by a desc) rn from t;
select * from v where rn < 4;
select a, sum(a) over w1, sum(a) over w2 from t window w1 as (order by a), w2 as (w1 rows 2 preceding);
select a, sum(a) over (w1 order by a) from t window w1 as (partition by b);
select a, sum(a) over (w1 partition by a) from t window w1 as (partition by b);
select a, sum(a) over nosuch from t;
select a, row_number() filter (where a > 1) over () from t;
select distinct sum(a) over () from t;
select count(distinct a) over () from t;
